BEGIN;
create temp table assertion_count(n integer);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create temp table st(k text primary key,v jsonb);
insert into public.properties(id,org_id,name)values('ee550000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','Website capture SQL fixture');
insert into public.property_chatbot_contexts(property_id,status,requires_review,context_markdown,last_generated_at)values('ee550000-0000-4000-8000-000000000001','current',false,'Prior exact context',clock_timestamp());
create function pg_temp.input(parent uuid default null)returns jsonb language sql as $$select jsonb_build_object('title','Exact website source','url','https://example.invalid/policy','materialId',coalesce(c.material_id::text,c.input->>'materialId'),'parentCaptureId',parent,'expectedParentRevision',c.revision,'reason','Retain exact synthetic website source')from(values(1))x(i)left join public.knowledge_web_captures c on c.id=parent$$;
create function pg_temp.begin_capture(i uuid,b jsonb default null)returns jsonb language sql as $$select public.begin_knowledge_web_capture(i,'ee550000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',coalesce(b,pg_temp.input()))$$;
create function pg_temp.command(i uuid,op text,extra jsonb default'{}')returns jsonb language sql as $$select jsonb_build_object('captureId',c.id,'expectedRevision',c.revision,'operation',op,'reason','Review exact synthetic website decision')||extra from public.knowledge_web_captures c where c.id=i$$;
create function pg_temp.decide(i uuid,b jsonb)returns jsonb language sql as $$select public.decide_knowledge_web_capture(i,'ee550000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',b)$$;
create function pg_temp.receipt(body text default E'Original website policy.\r\n🏡')returns jsonb language sql as $$select jsonb_build_object('recipe','public-utf8-html-v1','complete',true,'requestedUrl','https://example.invalid/policy','finalUrl','https://example.invalid/final','statusCode',200,'contentType','text/plain; charset=utf-8','fetchedAt',clock_timestamp()-interval'1 minute','body',body,'bodyHash',encode(extensions.digest(body,'sha256'),'hex'),'text',body,'limitations',jsonb_build_array('Synthetic static response, no network'))$$;
create function pg_temp.review(i uuid)returns jsonb language sql as $$select pg_temp.command(i,'accept',jsonb_build_object('receiptHash',c.receipt_hash,'content','Reviewed explicit website correction.','materialId',c.input->'materialId','previousVersionId',m.latest_version_id,'confirmed',true))from public.knowledge_web_captures c left join public.knowledge_materials m on m.id=(c.input->>'materialId')::uuid where c.id=i$$;
select pg_temp.check_it(pg_temp.begin_capture('ee550000-0000-4000-8000-000000000010')->>'state'='saved','capture intent retained');
select pg_temp.check_it(pg_temp.begin_capture('ee550000-0000-4000-8000-000000000010')->>'state'='replayed','lost request reply replays');
select pg_temp.check_it(pg_temp.begin_capture('ee550000-0000-4000-8000-000000000010',pg_temp.input()||'{"title":"Changed title"}')->>'state'='request_conflict','changed request rejected');
select pg_temp.check_it(not exists(select 1 from public.documents where property_id='ee550000-0000-4000-8000-000000000001')and not exists(select 1 from public.knowledge_materials where property_id='ee550000-0000-4000-8000-000000000001'),'request neither adds text nor publishes');
select pg_temp.check_it(pg_temp.begin_capture(gen_random_uuid(),pg_temp.input('ee550000-0000-4000-8000-000000000010'))->>'state'='still_running','new refresh requires earlier queued capture resolved');
insert into st values('claim',public.claim_knowledge_web_capture('ee550000-0000-4000-8000-000000000010'));
select pg_temp.check_it(v->>'state'='invoke_once','first claim permits one fetch')from st where k='claim';
select pg_temp.check_it(public.claim_knowledge_web_capture('ee550000-0000-4000-8000-000000000010')->>'state'='running','second claim never repeats fetch');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.command('ee550000-0000-4000-8000-000000000010','recover'))->>'state'='saved','recovery records only current status');
insert into st values('receipt',pg_temp.receipt());
select pg_temp.check_it(public.record_knowledge_web_capture('ee550000-0000-4000-8000-000000000010',gen_random_uuid(),(select v from st where k='receipt'))->>'state'='request_conflict','wrong claim cannot save result');
select pg_temp.check_it(public.record_knowledge_web_capture('ee550000-0000-4000-8000-000000000010',(select(v->>'claimToken')::uuid from st where k='claim'),(select v from st where k='receipt'))->>'state'='ready','complete exact response retained');
select pg_temp.check_it(public.record_knowledge_web_capture('ee550000-0000-4000-8000-000000000010',(select(v->>'claimToken')::uuid from st where k='claim'),(select v from st where k='receipt'))->>'state'='ready','lost receipt persistence reply replays');
select pg_temp.check_it(public.record_knowledge_web_capture('ee550000-0000-4000-8000-000000000010',(select(v->>'claimToken')::uuid from st where k='claim'),(select v||'{"text":"Changed"}'from st where k='receipt'))->>'state'='receipt_changed','retained extraction cannot be replaced');
select pg_temp.check_it((select status='current'and context_markdown='Prior exact context'from public.property_chatbot_contexts where property_id='ee550000-0000-4000-8000-000000000001'),'capture leaves current assistant facts intact');
insert into st values('review',pg_temp.review('ee550000-0000-4000-8000-000000000010'));
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),(select v||jsonb_build_object('receiptHash',repeat('b',64))from st where k='review'))->>'state'='capture_changed','acceptance requires exact retained result');
create function pg_temp.fail_web_review()returns trigger language plpgsql as $$begin if new.action='knowledge.web.reviewed'then raise exception 'Synthetic web review failure';end if;return new;end$$;
create trigger fixture_web_review_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_web_review();
do $$begin begin perform pg_temp.decide('ee550000-0000-4000-8000-000000000029',(select v from st where k='review'));raise exception 'Expected rollback'using errcode='P0002';exception when sqlstate'P0001'then if sqlerrm<>'Synthetic web review failure'then raise;end if;perform pg_temp.check_it(true,'history failure reaches atomic boundary');end;end$$;
drop trigger fixture_web_review_failure on public.shared_action_events;
select pg_temp.check_it(not exists(select 1 from public.knowledge_material_versions where property_id='ee550000-0000-4000-8000-000000000001')and not exists(select 1 from public.knowledge_web_links where property_id='ee550000-0000-4000-8000-000000000001'),'failed review rolls back private version and lineage');
insert into st values('accepted',pg_temp.decide('ee550000-0000-4000-8000-000000000020',(select v from st where k='review')));
select pg_temp.check_it(v->>'state'='saved'and v->'published'='false','review saves private source only')from st where k='accepted';
select pg_temp.check_it(pg_temp.decide('ee550000-0000-4000-8000-000000000020',(select v from st where k='review'))->>'state'='replayed','review loss recovers original private version');
select pg_temp.check_it((select content='Reviewed explicit website correction.'from public.knowledge_material_versions where id=(select(v->>'versionId')::uuid from st where k='accepted')),'deliberate operator correction retained exactly');
select pg_temp.check_it(public.knowledge_version_web_origin((select(v->>'versionId')::uuid from st where k='accepted'))->>'captureId'='ee550000-0000-4000-8000-000000000010','private source links exact capture');
select pg_temp.check_it(public.read_knowledge_materials('ee550000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('kind','version','materialId',(select v->>'materialId'from st where k='accepted')))->'webOrigin'->>'url'='https://example.invalid/final','source detail carries original URL');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.review('ee550000-0000-4000-8000-000000000010'))->>'state'='capture_changed','capture accepted only once');
select pg_temp.check_it(pg_temp.decide('ee550000-0000-4000-8000-000000000021',pg_temp.command('ee550000-0000-4000-8000-000000000010','download'))->'prepared'='true','exact original download preparation recorded');
select pg_temp.check_it(public.read_knowledge_web_captures('ee550000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"kind":"decision","decisionId":"ee550000-0000-4000-8000-000000000021"}')->>'bodyHash'=(select v->>'bodyHash'from st where k='receipt'),'download receipt binds exact original');
select pg_temp.check_it(public.cancel_unused_knowledge_decision('ee550000-0000-4000-8000-000000000010','ee550000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('inputHash',repeat('a',64),'reason','Cancel only unused capture'))->>'decisionDomain'='knowledge_web','cancel recovers a saved capture instead');
select pg_temp.check_it(public.cancel_unused_knowledge_decision('ee550000-0000-4000-8000-000000000099','ee550000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('inputHash',repeat('a',64),'reason','Cancel only unused capture'))->>'state'='cancelled','unused capture cancellation saved');
select pg_temp.check_it(pg_temp.begin_capture('ee550000-0000-4000-8000-000000000099')->>'state'='decision_cancelled','cancelled delayed request cannot save');
select pg_temp.check_it(pg_temp.begin_capture('ee550000-0000-4000-8000-000000000011',pg_temp.input('ee550000-0000-4000-8000-000000000010'))->>'state'='saved','explicit refresh preserves parent and destination');
insert into st values('claim2',public.claim_knowledge_web_capture('ee550000-0000-4000-8000-000000000011'));
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),pg_temp.command('ee550000-0000-4000-8000-000000000011','stop'))->>'state'='saved','running capture stopped');
select pg_temp.check_it(public.record_knowledge_web_capture('ee550000-0000-4000-8000-000000000011',(select(v->>'claimToken')::uuid from st where k='claim2'),pg_temp.receipt('Late complete website reply'))->>'state'='stopped','late complete receipt does not revive stopped capture');
select pg_temp.check_it((select receipt is not null from public.knowledge_web_captures where id='ee550000-0000-4000-8000-000000000011'),'late receipt retained');
select pg_temp.check_it(pg_temp.begin_capture('ee550000-0000-4000-8000-000000000012',pg_temp.input('ee550000-0000-4000-8000-000000000011'))->>'state'='saved','new capture follows stopped history');
insert into st values('claim3',public.claim_knowledge_web_capture('ee550000-0000-4000-8000-000000000012'));
select pg_temp.check_it(public.record_knowledge_web_capture('ee550000-0000-4000-8000-000000000012',(select(v->>'claimToken')::uuid from st where k='claim3'),pg_temp.receipt('New complete page'))->>'state'='ready','new receipt ready');
insert into st values('staleReview',pg_temp.review('ee550000-0000-4000-8000-000000000012'));
select public.save_knowledge_material('ee550000-0000-4000-8000-000000000030','ee550000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('materialId',(select v->>'materialId'from st where k='accepted'),'previousVersionId',(select v->>'versionId'from st where k='accepted'),'title','Manual correction preserving origin','content','Later private correction.','reason','Review revised source wording'));
-- Synthetic search receipts qualify integration without invoking a model.
create function pg_temp.publish_source(version uuid)returns jsonb language plpgsql as $$
declare v public.knowledge_material_versions;m public.knowledge_materials;i uuid:=gen_random_uuid();c jsonb;r jsonb;
begin select *into v from public.knowledge_material_versions where id=version;select *into m from public.knowledge_materials where id=v.material_id;
 perform public.begin_knowledge_search(i,v.property_id,v.actor_id,jsonb_build_object('materialId',m.id,'versionId',v.id,'contentHash',v.content_hash,'confirmed',true,'reason','Review synthetic search receipt'),jsonb_build_object('model','text-embedding-3-small','dimensions',1536,'recipe','lossless-utf8-4096-v1','contentHash',v.content_hash,'chunks',jsonb_build_array(v.content)));
 c:=public.claim_knowledge_search(i);r:=jsonb_build_object('status','received','providerRequestId','synthetic-no-network','response',jsonb_build_object('model','text-embedding-3-small','usage',jsonb_build_object('prompt_tokens',1,'total_tokens',1),'data',jsonb_build_array(jsonb_build_object('index',0,'embedding',(select jsonb_agg(case when n=1 then 1 else 0 end order by n)from generate_series(1,1536)n)))));
 perform public.record_knowledge_search_result(i,(c->>'claimToken')::uuid,r);perform public.validate_knowledge_search(i,(select result_hash from public.knowledge_embedding_requests where id=i));
 return public.release_knowledge_material(gen_random_uuid(),v.property_id,v.actor_id,jsonb_build_object('materialId',m.id,'versionId',v.id,'expectedLatestVersionId',m.latest_version_id,'expectedActiveVersionId',m.active_version_id,'expectedReleaseId',m.last_release_id,'operation','publish','confirmed',true,'reason','Approve exact synthetic source','resultHash',(select result_hash from public.knowledge_embedding_requests where id=i)));
end$$;
select pg_temp.check_it(pg_temp.publish_source('ee550000-0000-4000-8000-000000000030')->'published'='true','historical correction explicitly published');
select pg_temp.check_it((select source_type='website'and source_url='https://example.invalid/final'and last_synced_at=(select(v->>'fetchedAt')::timestamptz from st where k='receipt')from public.knowledge_sources where id=(select(v->>'materialId')::uuid from st where k='accepted')),'publication inherits actual capture time, not publication time');
select pg_temp.check_it(public.assistant_source_snapshot('ee550000-0000-4000-8000-000000000001')->'sources'->0->>'type'='website','assistant source set retains website freshness semantics');

select pg_temp.check_it(public.knowledge_version_web_origin('ee550000-0000-4000-8000-000000000030')->'inherited'='true','manual correction inherits capture origin');
select pg_temp.check_it(pg_temp.decide(gen_random_uuid(),(select v from st where k='staleReview'))->>'state'='source_changed','concurrent source correction prevents stale replacement');
select pg_temp.check_it(pg_temp.decide('ee550000-0000-4000-8000-000000000022',pg_temp.review('ee550000-0000-4000-8000-000000000012'))->>'state'='saved','replacement accepted against current source');
select set_config('p11.knowledge_web_scope','',true);
do $$begin begin update public.knowledge_web_captures set state='queued'where id='ee550000-0000-4000-8000-000000000010';raise exception 'guard missing'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'unrecorded capture mutation blocked');end;begin update public.knowledge_web_decisions set kind='changed'where id='ee550000-0000-4000-8000-000000000010';raise exception 'guard missing'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'retained review decisions immutable');end;end$$;
select pg_temp.check_it(not has_table_privilege('authenticated','public.knowledge_web_captures','select')and not has_function_privilege('anon','public.claim_knowledge_web_capture(uuid)','execute'),'raw website evidence and execution closed to public clients');
select pg_temp.check_it(public.read_knowledge_web_captures('ee550000-0000-4000-8000-000000000001',gen_random_uuid(),'{}')->>'state'='forbidden','current property access required');
select pg_temp.begin_capture('ee550000-0000-4000-8000-000000000013');
do $$declare prior_role text;begin select role into prior_role from public.profiles where id='11111111-1111-1111-1111-111111111111';update public.profiles set role=null where id='11111111-1111-1111-1111-111111111111';perform pg_temp.check_it(pg_temp.begin_capture(gen_random_uuid())->>'state'='forbidden','manager access rechecked at request');perform pg_temp.check_it(public.claim_knowledge_web_capture('ee550000-0000-4000-8000-000000000013')->>'state'='forbidden','access revoked before fetch claim blocks execution');update public.profiles set role=prior_role where id='11111111-1111-1111-1111-111111111111';end$$;
insert into st values('claim4',public.claim_knowledge_web_capture('ee550000-0000-4000-8000-000000000013'));
select pg_temp.check_it(public.record_knowledge_web_capture('ee550000-0000-4000-8000-000000000013',(select(v->>'claimToken')::uuid from st where k='claim4'),pg_temp.receipt()||jsonb_build_object('bodyHash',repeat('0',64)))->>'state'='held','mismatched original hash held');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where property_id='ee550000-0000-4000-8000-000000000001'and training_eligible),'no training eligibility');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where property_id='ee550000-0000-4000-8000-000000000001'and(request::text||result::text)like'%Reviewed explicit website correction%'),'private content absent from shared activity');
select pg_temp.check_it((select count(*)from public.shared_action_events where property_id='ee550000-0000-4000-8000-000000000001'and action='knowledge.web.received'and actor_id is null and service_principal='knowledge.web')=4,'machine receipts are separately attributed');

-- An explicitly different original supersedes inherited origins; ordinary edits preserve the nearest one.
select public.save_knowledge_material('ee550000-0000-4000-8000-000000000040','ee550000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('materialId',(select v->>'materialId'from st where k='accepted'),'previousVersionId',(select accepted_version_id from public.knowledge_web_captures where id='ee550000-0000-4000-8000-000000000012'),'title','Replacement original fixture','content','Explicit different file source.','reason','Synthetic file source lineage'));
insert into public.knowledge_files(id,property_id,org_id,actor_id,input,input_hash,storage_path)values('ee550000-0000-4000-8000-000000000041','ee550000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111','{"fileName":"new-original.txt","byteHash":"synthetic"}','synthetic','synthetic-file-lineage');
insert into public.knowledge_file_extractions(id,file_id,property_id,org_id,actor_id,input)values('ee550000-0000-4000-8000-000000000042','ee550000-0000-4000-8000-000000000041','ee550000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111','{}');
insert into public.knowledge_file_decisions(id,file_id,property_id,org_id,actor_id,kind,input,input_hash,result)values('ee550000-0000-4000-8000-000000000043','ee550000-0000-4000-8000-000000000041','ee550000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111','fixture','{}','fixture','{}');
insert into public.knowledge_file_links(version_id,material_id,file_id,extraction_id,decision_id,property_id,org_id,actor_id,receipt_hash,content_hash)values('ee550000-0000-4000-8000-000000000040',(select(v->>'materialId')::uuid from st where k='accepted'),'ee550000-0000-4000-8000-000000000041','ee550000-0000-4000-8000-000000000042','ee550000-0000-4000-8000-000000000043','ee550000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111','fixture','fixture');
select pg_temp.check_it(public.knowledge_version_web_origin('ee550000-0000-4000-8000-000000000040')is null and public.knowledge_version_file_origin('ee550000-0000-4000-8000-000000000040')->>'fileName'='new-original.txt','new file origin supersedes older website ancestry');
select pg_temp.begin_capture('ee550000-0000-4000-8000-000000000014',pg_temp.input('ee550000-0000-4000-8000-000000000012'));
insert into st values('claim5',public.claim_knowledge_web_capture('ee550000-0000-4000-8000-000000000014'));
select public.record_knowledge_web_capture('ee550000-0000-4000-8000-000000000014',(select(v->>'claimToken')::uuid from st where k='claim5'),pg_temp.receipt('Newer website source replaces file'));
insert into st values('accepted5',pg_temp.decide('ee550000-0000-4000-8000-000000000025',pg_temp.review('ee550000-0000-4000-8000-000000000014')));
select pg_temp.check_it(public.knowledge_version_file_origin((select(v->>'versionId')::uuid from st where k='accepted5'))is null and public.knowledge_version_web_origin((select(v->>'versionId')::uuid from st where k='accepted5'))->>'captureId'='ee550000-0000-4000-8000-000000000014','new website origin supersedes older file ancestry');
-- An old, synthetic in-flight response remains old when reviewed and published today.
insert into public.knowledge_web_captures(id,property_id,org_id,actor_id,input,input_hash,state,claim_token,started_at)values('ee550000-0000-4000-8000-000000000015','ee550000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111',pg_temp.input(),'fixture','running','ee550000-0000-4000-8000-000000000016',clock_timestamp()-interval'8 days');
select public.record_knowledge_web_capture('ee550000-0000-4000-8000-000000000015','ee550000-0000-4000-8000-000000000016',pg_temp.receipt('Eight day old original')||jsonb_build_object('fetchedAt',clock_timestamp()-interval'8 days'));
insert into st values('oldAccepted',pg_temp.decide('ee550000-0000-4000-8000-000000000026',pg_temp.review('ee550000-0000-4000-8000-000000000015')));
select pg_temp.check_it(pg_temp.publish_source((select(v->>'versionId')::uuid from st where k='oldAccepted'))->'published'='true','older source publication retains its actual age');
select public.save_assistant_fact_draft('ee550000-0000-4000-8000-000000000060','ee550000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('operation','prepare','expectedDraftId',v->'workspace'->'latest_version_id','expectedSourceHash',v->>'sourceHash','expectedContextHash',v->>'contextHash','markdown',null,'reason','Review complete synthetic facts'))from(select public.read_assistant_facts('ee550000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111')v)x;
select public.release_assistant_facts('ee550000-0000-4000-8000-000000000061','ee550000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('operation','publish','versionId',v->'selected'->>'id','expectedDraftId',v->'workspace'->'latest_version_id','expectedActiveId',v->'workspace'->'active_version_id','expectedReleaseId',v->'workspace'->'last_release_id','expectedContextHash',v->>'contextHash','markdownHash',v->'selected'->>'markdown_hash','confirmed',true,'reason','Review exact synthetic publication'))from(select public.read_assistant_facts('ee550000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111')v)x;
select pg_temp.check_it(public.read_serving_assistant_facts('ee550000-0000-4000-8000-000000000001')->>'freshnessReviewReason'='website_freshness_review_due' and public.read_serving_assistant_facts('ee550000-0000-4000-8000-000000000001')->>'state'='ready','explicitly reviewed older website facts remain available with a freshness reminder');
insert into st values('page',public.read_knowledge_web_captures('ee550000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{}'));
insert into public.knowledge_web_captures(id,property_id,org_id,actor_id,input,input_hash)select md5('website-capture-'||n)::uuid,'ee550000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111',pg_temp.input(),'fixture'from generate_series(1,1001)n;
select pg_temp.check_it(public.read_knowledge_web_captures('ee550000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('offset',20,'expectedHash',(select v->>'historyHash'from st where k='page')))->>'state'='history_changed','changed capture page held');
insert into st values('tail',public.read_knowledge_web_captures('ee550000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"offset":1000}'));
select pg_temp.check_it(v->>'total'='1007'and jsonb_array_length(v->'items')=7 and v->'nextOffset'='null','complete capture history beyond REST cap')from st where k='tail';
insert into public.knowledge_web_decisions(id,capture_id,property_id,org_id,actor_id,kind,input,input_hash,result)select md5('website-decision-'||n)::uuid,'ee550000-0000-4000-8000-000000000010','ee550000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111','fixture','{}','fixture','{}'from generate_series(1,1001)n;
insert into st values('decisionTail',public.read_knowledge_web_captures('ee550000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"kind":"decisions","captureId":"ee550000-0000-4000-8000-000000000010","offset":1000}'));
select pg_temp.check_it((v->>'total')::int>1001 and jsonb_array_length(v->'items')=(v->>'total')::int-1000,'complete decision history beyond REST cap')from st where k='decisionTail';
select n as passed_assertions from assertion_count;
ROLLBACK;
